import{_ as t,o,c as a,a6 as i}from"./chunks/framework.4tsfTCyC.js";const g=JSON.parse('{"title":"LaTeX Tools","description":"","frontmatter":{},"headers":[],"relativePath":"guide/latex-tools.md","filePath":"guide/latex-tools.md"}'),r={name:"guide/latex-tools.md"};function n(s,e,l,d,c,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="latex-tools" tabindex="-1">LaTeX Tools <a class="header-anchor" href="#latex-tools" aria-label="Permalink to &quot;LaTeX Tools&quot;">​</a></h1><p>TeXRA doesn&#39;t just send text to an AI and hope for the best. It plugs into battle-tested LaTeX tools so formatting, diffing, and figure extraction are handled by the right software—not by a language model guessing at syntax.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What it does</th><th>Tool behind the scenes</th></tr></thead><tbody><tr><td>Code formatting</td><td><code>latexindent</code> or <code>tex-fmt</code></td></tr><tr><td>Version comparison</td><td><code>latexdiff</code></td></tr><tr><td>Document statistics</td><td><code>texcount</code></td></tr><tr><td>Figure extraction</td><td>Built-in</td></tr><tr><td>TikZ compilation</td><td>Built-in</td></tr><tr><td>Bibliography resolution</td><td>Built-in</td></tr></tbody></table><h2 id="formatting-tools" tabindex="-1">Formatting Tools <a class="header-anchor" href="#formatting-tools" aria-label="Permalink to &quot;Formatting Tools&quot;">​</a></h2><p>TeXRA uses formatters to ensure consistent, readable LaTeX code.</p><p><strong>Supported formatters:</strong></p><ul><li><strong>latexindent</strong> - The default formatter, highly configurable</li><li><strong>tex-fmt</strong> - A faster alternative with simpler configuration</li></ul><p>Formatting runs automatically after agent execution and is available via the <code>TeXRA: Format Document</code> command.</p><p><strong>Configuration:</strong> See <a href="./configuration.html#latex-configuration">VS Code Settings</a> for formatter selection and options.</p><h2 id="version-comparison-with-latexdiff" tabindex="-1">Version Comparison with latexdiff <a class="header-anchor" href="#version-comparison-with-latexdiff" aria-label="Permalink to &quot;Version Comparison with latexdiff&quot;">​</a></h2><p>The <code>latexdiff</code> tool visualizes changes between document versions, generating a PDF with additions and deletions clearly marked. TeXRA can automatically generate diffs after agent runs.</p><p><strong>Usage:</strong></p><ul><li>After an agent modifies your document, a diff PDF shows exactly what changed</li><li>Use <code>latexdiff-vc</code> to compare against git history</li></ul><p><strong>Configuration:</strong> See the <a href="./latex-diff.html">LaTeX Diff guide</a> for detailed setup and options.</p><h2 id="document-statistics-with-texcount" tabindex="-1">Document Statistics with texcount <a class="header-anchor" href="#document-statistics-with-texcount" aria-label="Permalink to &quot;Document Statistics with texcount&quot;">​</a></h2><p><code>texcount</code> provides document statistics including word counts, heading counts, and math element counts. This information helps the LLM understand document scale and structure.</p><p><strong>Enabling texcount:</strong></p><ol><li><strong>For context:</strong> Enable &quot;Attach TeX Count&quot; in the Tool Configuration dropdown (see <a href="./file-management.html#tool-config-dropdown">File Management</a>)</li><li><strong>As a tool:</strong> Tool-use agents can invoke <code>texcount</code> directly to analyze files on demand</li></ol><p><strong>Modes:</strong></p><ul><li><code>separate</code> (default) - Count each file independently</li><li><code>include</code> - Follow <code>\\input{}</code>/<code>\\include{}</code> directives from the main file</li><li><code>sum</code> - Aggregate totals across multiple top-level files</li></ul><div class="warning custom-block"><p class="custom-block-title">Requirement</p><p>Ensure <code>texcount</code> is in your system&#39;s PATH. It&#39;s typically included with TeX distributions.</p></div><h2 id="figure-extraction" tabindex="-1">Figure Extraction <a class="header-anchor" href="#figure-extraction" aria-label="Permalink to &quot;Figure Extraction&quot;">​</a></h2><p>TeXRA extracts and processes figures for AI analysis.</p><h3 id="standard-figures" tabindex="-1">Standard Figures <a class="header-anchor" href="#standard-figures" aria-label="Permalink to &quot;Standard Figures&quot;">​</a></h3><p>The <code>extract_figures</code> tool finds figure references (<code>\\includegraphics</code>) and returns the images as attachments, allowing the LLM to &quot;see&quot; your figures.</p><p><strong>Auto-extraction:</strong> Enable &quot;Auto Extract Figures&quot; in the UI to automatically include figures in prompts. See <a href="./working-with-figures.html">Working with Figures</a>.</p><h3 id="tikz-figures" tabindex="-1">TikZ Figures <a class="header-anchor" href="#tikz-figures" aria-label="Permalink to &quot;TikZ Figures&quot;">​</a></h3><p>The <code>extract_tikz_figures</code> tool discovers TikZ environments, compiles them to standalone PDFs, and returns the rendered output.</p><p><strong>Requirements:</strong></p><ul><li><code>latexmk</code> (preferred) or <code>pdflatex</code></li><li><code>GraphicsMagick</code> or <code>ImageMagick</code> (for conversion)</li><li><code>Ghostscript</code> (for PDF processing)</li></ul><p>See the <a href="./tikz-figures.html">TikZ Figures guide</a> for detailed workflows and the <a href="./installation.html">Installation guide</a> for dependency setup.</p><h2 id="bibliography-extraction" tabindex="-1">Bibliography Extraction <a class="header-anchor" href="#bibliography-extraction" aria-label="Permalink to &quot;Bibliography Extraction&quot;">​</a></h2><p>The <code>extract_bib_entries</code> tool resolves bibliography context for your LaTeX document:</p><ol><li>Finds <code>\\bibliography{}</code> and <code>\\addbibresource{}</code> directives</li><li>Loads the referenced <code>.bib</code> files</li><li>Returns BibTeX entries for every cited key</li></ol><p>This is useful when the agent needs exact citation records to edit, format, or validate references.</p><h2 id="symbolic-math-with-wolfram" tabindex="-1">Symbolic Math with Wolfram <a class="header-anchor" href="#symbolic-math-with-wolfram" aria-label="Permalink to &quot;Symbolic Math with Wolfram&quot;">​</a></h2><p>The <code>wolfram</code> tool executes Wolfram Language code through <code>wolframscript</code>, letting agents verify calculations or perform symbolic algebra. While not LaTeX-specific, it&#39;s particularly useful for validating mathematical content in your documents.</p><h2 id="configuring-tool-usage" tabindex="-1">Configuring Tool Usage <a class="header-anchor" href="#configuring-tool-usage" aria-label="Permalink to &quot;Configuring Tool Usage&quot;">​</a></h2><p>Control how TeXRA uses tools through the UI:</p><ul><li><strong>Tool Config Dropdown:</strong> Enable/disable helpers like &quot;Attach TeX Count&quot; or &quot;Attach Diagnostics&quot; for the current run. See <a href="./configuration.html#agent-execution-settings-webview-interface">Configuration</a>.</li><li><strong>Auto Extract Dropdown:</strong> Enable/disable automatic extraction of Figures or TikZ Figures. See <a href="./working-with-figures.html">Working with Figures</a>.</li></ul><p>For detailed tool settings (formatter paths, TikZ processing options, etc.), see the <a href="./configuration.html">Configuration guide</a>.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./tikz-figures.html">TikZ Figures</a> - Advanced TikZ workflows</li><li><a href="./latex-diff.html">LaTeX Diff</a> - Version comparison in detail</li><li><a href="./research-tools.html">Research Tools</a> - arXiv, Crossref, and web search</li></ul>',44)])])}const f=t(r,[["render",n]]);export{g as __pageData,f as default};
